def reachableNodes(edges: list[list[int]], maxMoves: int, n: int) -> int:
    import heapq
    from collections import defaultdict
    graph = defaultdict(dict)
    for u, v, w in edges:
        graph[u][v] = w
        graph[v][u] = w
    pq = [(0, 0)]
    dist = {}
    while pq:
        d, u = heapq.heappop(pq)
        if u in dist: continue
        dist[u] = d
        for v, w in graph[u].items():
            if v not in dist and d + w + 1 <= maxMoves:
                heapq.heappush(pq, (d + w + 1, v))
    ans = len(dist)
    for u, v, w in edges:
        c1 = max(0, maxMoves - dist[u]) if u in dist else 0
        c2 = max(0, maxMoves - dist[v]) if v in dist else 0
        ans += min(w, c1 + c2)
    return ans

